import json
with open('/tmp/trace3.json') as f:
    data = json.load(f)
msgs = data['transcripts'][0]['messages']

# Count system [agent.start] messages and get their times
import re
agent_starts = []
for i, m in enumerate(msgs):
    if m.get('role') == 'system':
        content = m.get('content', '')
        if isinstance(content, str) and 'agent.start' in content:
            tm = re.search(r'Current time: (.+)', content)
            if tm:
                agent_starts.append((i, tm.group(1)))

print(f"Total agent.start system messages: {len(agent_starts)}")
print("First 5:")
for s in agent_starts[:5]: print(s)
print("Last 5:")
for s in agent_starts[-5:]: print(s)
